from example import flatten_dict


# --- Happy path tests ---

def test_flatten_flat_dict():
    """A flat dict should remain unchanged."""
    d = {'a': 1, 'b': 2}
    assert flatten_dict(d) == {'a': 1, 'b': 2}

def test_flatten_single_nested_dict():
    """Single level of nesting should be flattened with default separator '.'."""
    d = {'a': 1, 'b': {'c': 2, 'd': 3}}
    expected = {'a': 1, 'b.c': 2, 'b.d': 3}
    assert flatten_dict(d) == expected

def test_flatten_deeply_nested_dict():
    """Multiple levels of nesting should produce keys joined by '.'."""
    d = {'x': {'y': {'z': 1}}}
    expected = {'x.y.z': 1}
    assert flatten_dict(d) == expected

def test_flatten_custom_separator():
    """A custom separator should be used in the concatenated keys."""
    d = {'a': {'b': 1}}
    expected = {'a_b': 1}
    assert flatten_dict(d, sep='_') == expected

def test_flatten_with_parent_key():
    """Providing a parent_key should prepend it to all keys."""
    d = {'a': 1}
    expected = {'parent.a': 1}
    assert flatten_dict(d, parent_key='parent') == expected

def test_flatten_mixed_value_types():
    """Non-dict values (lists, None, floats, etc.) are kept as leaf values."""
    d = {'a': [1, 2], 'b': None, 'c': {'d': 3.14}}
    expected = {'a': [1, 2], 'b': None, 'c.d': 3.14}
    assert flatten_dict(d) == expected

def test_flatten_non_string_keys():
    """Keys that are not strings work because f-str converts them to str."""
    d = {1: {'a': 2}}
    expected = {'1.a': 2}
    assert flatten_dict(d) == expected

# --- Edge case tests ---

def test_flatten_empty_dict():
    """Flattening an empty dictionary returns an empty dictionary."""
    assert flatten_dict({}) == {}

def test_flatten_nested_empty_dict():
    """An empty nested dict has no items, so its key disappears in the result."""
    d = {'a': {}}
    assert flatten_dict(d) == {}

def test_flatten_nested_empty_dict_with_parent():
    """Empty nested dict with an explicit parent_key should also disappear."""
    d = {'a': {}}
    assert flatten_dict(d, parent_key='parent') == {}

def test_flatten_multiple_empty_nested():
    """Multiple empty nested dicts all vanish."""
    d = {'a': {}, 'b': {'c': {}}}
    assert flatten_dict(d) == {}

# --- Error case tests ---

def test_flatten_non_dict_input():
    """Passing a non-dict should raise an AttributeError (no .items())."""
    with pytest.raises(AttributeError):
        flatten_dict([1, 2, 3])

    with pytest.raises(AttributeError):
        flatten_dict("not a dict")
